package rules

import (
	"bytes"
	"fmt"
	"main/types"
	"reflect"
	"sort"
	"strings"
)

// TypeScriptHeader explains where the generated rule IDs come from.
const TypeScriptHeader = `/**
 * This file is auto-generated by the rules-ids command of the Go validator.
 * Do not edit this file manually. Run ` + "`npm run repo:validator-rules`" + ` to regenerate.
 *
 * Source: types.GtfsRules in modules/operation/apps/validator/validator/src.
 * Includes configured rule IDs and fixed runtime notice IDs, excluding parser diagnostics and shared output IDs.
 */
`

var severityType = reflect.TypeOf(types.Severity(""))

// TypeScript renders only the shared TypeScript rule IDs and their Zod schema.
func TypeScript() (map[string][]byte, error) {
	return RenderTypeScript(reflect.TypeOf(types.GtfsRules{}))
}

// RenderTypeScript reads rule IDs directly from the Go configuration fields.
func RenderTypeScript(root reflect.Type) (map[string][]byte, error) {
	if root.Kind() != reflect.Struct {
		return nil, fmt.Errorf("rules root %s is not a struct", root)
	}
	ids := []string{"file_validation", "file_not_found_in_rules"}
	for i := range root.NumField() {
		group := root.Field(i)
		name, err := jsonName(group)
		if err != nil {
			return nil, err
		}
		if group.Type.Kind() != reflect.Struct {
			return nil, fmt.Errorf("section %s has unsupported type %s", name, group.Type)
		}
		for j := range group.Type.NumField() {
			field := group.Type.Field(j)
			id, err := jsonName(field)
			if err != nil {
				return nil, fmt.Errorf("%s: %w", name, err)
			}
			switch field.Type {
			case ruleConfigType:
				ids = append(ids, id)
			case severityType:
				if id != "_file" {
					return nil, fmt.Errorf("%s.%s: only _file may be a severity field", name, id)
				}
				if name != "file_validation" {
					ids = append(ids, name+"_file_missing")
				}
			default:
				return nil, fmt.Errorf("%s.%s has unsupported type %s", name, id, field.Type)
			}
		}
	}
	sort.Strings(ids)
	for i := 1; i < len(ids); i++ {
		if ids[i] == ids[i-1] {
			return nil, fmt.Errorf("duplicate rule id %s", ids[i])
		}
	}

	var output bytes.Buffer
	output.WriteString("/* * */\n\nimport { z } from 'zod';\n\n/* * */\n\n")
	output.WriteString(TypeScriptHeader)
	output.WriteString("\nexport const GtfsValidatorRuleIdValues = [\n")
	for _, id := range ids {
		fmt.Fprintf(&output, "\t%s,\n", quote(id))
	}
	output.WriteString(`] as const;

export const GtfsValidatorRuleIdSchema = z
	.string()
	.transform(value => String(value).toLowerCase())
	.pipe(z.enum(GtfsValidatorRuleIdValues));

export type GtfsValidatorRuleId = z.infer<typeof GtfsValidatorRuleIdSchema>;
`)
	return map[string][]byte{"rule-ids.ts": output.Bytes()}, nil
}

func jsonName(field reflect.StructField) (string, error) {
	tag, ok := field.Tag.Lookup("json")
	if !ok {
		return "", fmt.Errorf("field %s has no json tag", field.Name)
	}
	name, _, _ := strings.Cut(tag, ",")
	if name == "" || name == "-" {
		return "", fmt.Errorf("field %s has unsupported json tag %q", field.Name, tag)
	}
	return name, nil
}

var tsStringEscaper = strings.NewReplacer(`\`, `\\`, "'", `\'`, "\n", `\n`, "\r", `\r`)

// quote renders a single-quoted TypeScript string literal.
func quote(value string) string {
	return "'" + tsStringEscaper.Replace(value) + "'"
}
